interface PreviewBridge {
  readonly captureScreenshot: (tabId: string) => Promise<string>
  readonly recording: { readonly startScreencast: (tabId: string) => Promise<string> }
}

const nativePreviewBridge: PreviewBridge | null =
  typeof window === "undefined" ? null : (window.desktopBridge?.preview ?? null)

export const previewBridge = nativePreviewBridge
  ? {
      ...nativePreviewBridge,
      captureScreenshot: async (tabId: string) => (await nativePreviewBridge.captureScreenshot(tabId)).trim(),
      recording: {
        ...nativePreviewBridge.recording,
        startScreencast: async (tabId: string) => (await nativePreviewBridge.recording.startScreencast(tabId)).trim(),
      },
    }
  : null
